items.referenceSolution:
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    ofstream out("num.dat", ios::binary);
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        out.write((char*)&x, sizeof(x));
    }
    out.close();

    ifstream in("num.dat", ios::binary);
    int x = 0;
    int total = 0;
    while (in.read((char*)&x, sizeof(x))) {
        total = total + x;
    }
    cout << "一共 " << total << " 条" << endl;
    return 0;
}

