#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    ofstream out("list.txt");
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        out << "小鱼干 " << x << endl;
    }
    out.close();

    ifstream in("list.txt");
    string line;
    int row = 0;
    while (getline(in, line)) {
        row = row + 1;
        cout << "第 " << row << " 行：" << line << endl;
    }
    cout << "一共 " << row << " 行" << endl;
    return 0;
}

